steps.solutionCode:
const courses = [
  { name: '리액트 입문', hours: 8, describe() { return this.name + ' · ' + this.hours + '시간'; } },
  { name: 'CSS 레이아웃', hours: 6, describe() { return this.name + ' · ' + this.hours + '시간'; } },
];

function listAll() {
  const lines = courses.map((course) => course.describe());

  return lines.join(' / ');
}

function whoseTag() {
  return this && this.tag ? this.tag : '없음';
}

function Maker() {
  this.tag = '새것';
}

function tell(kind) {
  if (kind === 'plain') {
    return whoseTag();
  }

  if (kind === 'method') {
    const holder = { tag: '메서드', ask: whoseTag };
    return holder.ask();
  }

  if (kind === 'new') {
    return new Maker().tag;
  }

  return '모르는 방식';
}
